package xyz.toesinthesand.ashfall.salvage.city;

import java.util.List;

/**
 * Ashfall's landmark buildings (plan section 1.6, first batch). The buildings themselves are Lost Cities
 * assets in {@code data/ashfall/lostcities/}, generated by {@code tools/landmarks/build_landmarks.py}, and
 * the predefined cities in {@code data/ashfall/lostcities/predefinedcities/} pin each one to a fixed chunk
 * of its district. This class only knows their ids and the few interior positions code needs, so nothing
 * outside the Lost Cities bridge has to touch Lost Cities types.
 * <p>
 * Multi-chunk landmarks are Lost Cities multibuildings whose per-chunk buildings are named
 * {@code <landmark>_<cx><cz>} (for example {@code ashfall:hospital_21}).
 */
public final class Landmarks {
	public static final String NAMESPACE = "ashfall";
	public static final String SAFEHOUSE = "ashfall:safehouse";
	/** Every landmark id, single-chunk buildings and multibuildings alike. */
	public static final List<String> ALL = List.of(SAFEHOUSE, "ashfall:pharmacy", "ashfall:police_station",
			"ashfall:hospital", "ashfall:kiln_warehouse", "ashfall:substation_river_arts",
			"ashfall:substation_south_slope", "ashfall:substation_downtown", "ashfall:substation_mission");
	/**
	 * Where a new player stands in the safehouse, relative to its chunk's north-west corner and the
	 * ground-floor slab: the front hall, facing the stairs, inside the front door.
	 */
	public static final int SAFEHOUSE_SPAWN_X = 6, SAFEHOUSE_SPAWN_Z = 12;

	private Landmarks() {
	}

	/** True for a Lost Cities building id that belongs to one of our landmarks (any chunk of it). */
	public static boolean isLandmarkBuilding(String buildingId) {
		if (buildingId == null) {
			return false;
		}
		for (String id : ALL) {
			if (buildingId.equals(id) || buildingId.startsWith(id + "_")) {
				return true;
			}
		}
		return false;
	}
}
